function extract($, ctx) {
  const items = [];

  // --- Try JSON‑LD first -------------------------------------------------
  $('script[type="application/ld+json"]').each((_, el) => {
    try {
      const data = JSON.parse($(el).text());

      // Handle possible @graph wrapper or array
      let menu = data;
      if (Array.isArray(data)) {
        for (const d of data) {
          if (d["@type"] === "Menu") {
            menu = d;
            break;
          }
        }
      }
      if (!menu || menu["@type"] !== "Menu") return;

      const sections = menu.hasMenuSection || [];
      sections.forEach(sec => {
        const sectionName = sec.name ?? null;
        const menuItems = sec.hasMenuItem || [];
        menuItems.forEach(it => {
          const name = cleanText(it.name ?? "");
          if (!name) return;
          const description = it.description ? cleanText(it.description) : null;
          let price = null;
          if (it.offers && typeof it.offers.price !== "undefined") {
            price = parsePrice(String(it.offers.price));
          }
          items.push({ section: sectionName, name, description, price });
        });
      });
    } catch (_) {
      // malformed JSON‑LD – ignore
    }
  });

  // --- Fallback to DOM parsing -------------------------------------------
  if (items.length === 0) {
    const $menuRoot = $('#menu-root');
    if ($menuRoot.length) {
      $menuRoot.find('.menu-group').each((_, secEl) => {
        const $sec = $(secEl);
        const sectionName = $sec.find('.menu-group__title')
          .text()
          .trim()
          || null;

        $sec.find('.dish').each((_, dishEl) => {
          const $dish = $(dishEl);
          const nameRaw = $dish.find('.dish__name').text() || "";
          const name = cleanText(nameRaw);
          if (!name) return;

          const descRaw = $dish.find('.dish__desc').text() || "";
          const description = descRaw ? cleanText(descRaw) : null;

          const priceRaw = $dish.find('.dish__price').text() || "";
          const price = parsePrice(priceRaw);

          items.push({ section: sectionName, name, description, price });
        });
      });
    }
  }

  // --- Deduplicate exact duplicates ---------------------------------------
  const seen = new Set();
  const deduped = [];
  for (const it of items) {
    const key = `${it.section ?? ""}|${it.name}|${it.description ?? ""}|${it.price ?? ""}`;
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(it);
    }
  }
  return deduped;
}
